/*selectMasterCmClPurchaseTaxsheetAgntcmpySumCreationList*/
SELECT MAX(KEP_IRS_NAME) AS KEP_IRS_NAME , MAX(SITE_GUBUN_NAME) AS SITE_GUBUN_NAME , MAX(AGENT_IRS_NO) AS AGENT_IRS_NO , MAX(AGENT_COM_NAME_LOC) AS AGENT_NAME , KEP_DEPT , MAX(BUYER_COM_NAME_LOC) AS BUYER_NAME , SUM(GR_AMT) AS GR_AMT , SUM(GR_AGENT_IMT) AS GR_AGENT_AMT , BUYER , MAX(KEP_IRS_NO) AS KEP_IRS_NO /* , MAX(KEP_DEPT_ORG) AS KEP_DEPT_ORG */ , KEP_DEPT AS KEP_DEPT_ORG , AGENT , MAX(GR_FROM_DATE) AS GR_FROM_DATE , MAX(GR_TO_DATE) AS GR_TO_DATE , MAX(KEP_COM_CODE) AS KEP_COM_CODE , 'Y' AS NTS_SEND_FLAG , MAX(CMP_CLOSE_FLAG) AS CMP_CLOSE_FLAG , (SELECT SP_TYPE FROM SUPLINFO2 WHERE SUPPLIER = AGENT) AS SP_TYPE FROM ( /* ICOMGRDT.PROCESS_TYPE = '0' 직납 또는 ICOMGRDT.PROCESS_TYPE = '2' 재고 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_COM_NAME_LOC , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE, 1, 4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = GR.BUYER) BUYER_COM_NAME_LOC , ROUND((GR.ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AMT , ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AGENT_IMT , GR.BUYER AS BUYER , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO /* , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE, 1, 4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_ORG */ , GR.AGENT AS AGENT , #{st_from_date} AS GR_FROM_DATE , #{st_to_date} AS GR_TO_DATE , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , GR.NTS_SEND_FLAG AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ , ICOMCMPY BCM /* 회원사정보 */ WHERE 1=1 AND GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND GR.AGENT = CM.COM_CODE AND GR.BUYER = BCM.COM_CODE AND GR.AP_BILL_FLAG = 'N' AND GR.AR_BILL_FLAG = 'Y' AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE IN ('0', '2') AND POHD.DOC_TYPE <> 'X' AND GR.BUYER = COD.TEXT1(+) AND GR.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND GR.AGENT NOT IN ( SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND GR.BUYER IN
#{item}
AND GR.AGENT = #{st_agent_code}
AND CM.IRS_NO LIKE #{st_po_no} || '%'
AND GR.CLOSE_USER_ID = #{st_ar_add_user_id}
UNION ALL
/* ICOMGRDT.PROCESS_TYPE = '3' VMI 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_COM_NAME_LOC , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE, 1, 4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = GR.BUYER) BUYER_COM_NAME_LOC , ROUND((GR.ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AMT , ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AGENT_IMT , GR.BUYER AS BUYER , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO /* , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE, 1, 4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_ORG */ , PODT.WAREHOUSE_CODE AS AGENT , #{st_from_date} AS GR_FROM_DATE , #{st_to_date} AS GR_TO_DATE , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , GR.NTS_SEND_FLAG AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ , ICOMCMPY BCM /* 회원사정보 */ WHERE 1=1 AND GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND PODT.WAREHOUSE_CODE = CM.COM_CODE AND GR.BUYER = BCM.COM_CODE AND GR.AP_BILL_FLAG = 'N' AND GR.AR_BILL_FLAG = 'Y' AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE = '3' AND POHD.DOC_TYPE <> 'X' AND PODT.BUYER = COD.TEXT1(+) AND PODT.WAREHOUSE_CODE = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND PODT.WAREHOUSE_CODE NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND GR.BUYER IN
#{item}
AND PODT.WAREHOUSE_CODE = #{st_agent_code}
AND CM.IRS_NO LIKE #{st_po_no} || '%'
AND GR.CLOSE_USER_ID = #{st_ar_add_user_id}
UNION ALL
/* ICOMGRDT.PROCESS_TYPE = '1' 재고 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_COM_NAME_LOC , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE, 1, 4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = GR.BUYER) BUYER_COM_NAME_LOC , ROUND((GR.ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AMT , ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AGENT_IMT , GR.BUYER AS BUYER , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO /* , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE, 1, 4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_ORG */ , GR.AGENT AS AGENT , #{st_from_date} AS GR_FROM_DATE , #{st_to_date} AS GR_TO_DATE , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , GR.NTS_SEND_FLAG AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ , ICOMCMPY BCM /* 회원사정보 */ WHERE 1=1 AND GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND GR.AGENT = CM.COM_CODE AND GR.BUYER = BCM.COM_CODE AND GR.AP_BILL_FLAG = 'N' AND GR.BUYER IN (select text1 from ICOMCOD1 WHERE TYPE = 'HUB') AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE = '1' AND GR.AGENT NOT IN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT4 = 'S' AND FLAG = 'Y') /* VMI 이고, AGENT = '물류센타' 일 경우 제외시킴 */ AND POHD.DOC_TYPE <> 'X' AND GR.BUYER = COD.TEXT1(+) AND GR.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND GR.AGENT NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND GR.BUYER IN
#{item}
AND GR.AGENT = #{st_agent_code}
AND CM.IRS_NO LIKE #{st_po_no} || '%'
AND GR.CLOSE_USER_ID = #{st_ar_add_user_id}
) X GROUP BY AGENT , KEP_DEPT , BUYER ORDER BY MAX(AGENT_COM_NAME_LOC) , KEP_DEPT DESC , MAX(BUYER_COM_NAME_LOC)

