SELECT MAX(KEP_IRS_NAME) AS KEP_IRS_NAME , MAX(SITE_GUBUN_NAME) AS SITE_GUBUN_NAME , MAX(AGENT_IRS_NO) AS AGENT_IRS_NO , MAX(AGENT_COM_NAME_LOC) AS AGENT_NAME , KEP_DEPT , MAX(BUYER_COM_NAME_LOC) AS BUYER_NAME , SUM(INV_AMT) AS INV_AMT , SUM(INV_AGENT_IMT) AS INV_AGENT_AMT , BUYER , MAX(KEP_IRS_NO) AS KEP_IRS_NO , KEP_DEPT AS KEP_DEPT_ORG , AGENT , MAX(INV_FROM_DATE) AS INV_FROM_DATE , MAX(INV_TO_DATE) AS INV_TO_DATE , MAX(KEP_COM_CODE) AS KEP_COM_CODE , 'Y' AS NTS_SEND_FLAG , MAX(CMP_CLOSE_FLAG) AS CMP_CLOSE_FLAG , (SELECT SP_TYPE FROM SUPLINFO2 WHERE SUPPLIER = AGENT) AS SP_TYPE FROM ( /* ICOMIVDTD.PROCESS_TYPE = '0' 직납 또는 ICOMGRDT.PROCESS_TYPE = '2' 재고 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_COM_NAME_LOC , CASE WHEN IV.AP_CLOSE_DEPT IS NOT NULL THEN IV.AP_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE, 1, 4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = IV.BUYER) BUYER_COM_NAME_LOC , ROUND((IV.ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))) AS INV_AMT , ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))) AS INV_AGENT_IMT , IV.BUYER AS BUYER , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , IV.AGENT AS AGENT , #{st_from_date} AS INV_FROM_DATE , #{st_to_date} AS INV_TO_DATE , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG FROM ICOMIVDT IV /* 구매사별 납품정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ , ICOMCMPY BCM /* 회원사정보 */ WHERE 1=1 AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND IV.AGENT = CM.COM_CODE AND IV.BUYER = BCM.COM_CODE AND NVL(IV.AP_BILL_FLAG,'N') = 'N' AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND IV.PROCESS_TYPE IN ('0', '2') AND POHD.DOC_TYPE <> 'X' AND IV.BUYER = COD.TEXT1(+) AND IV.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND IV.AGENT NOT IN ( SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA')
AND IV.BUYER IN
#{item}
AND IV.AGENT = #{st_agent_code}
AND CM.IRS_NO LIKE #{st_po_no} || '%'
AND DECODE(IV.PROCESS_TYPE,'0',(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE GR.BUYER = IV.BUYER AND GR.INV_NO = IV.INV_NO AND GR.INV_SEQ = IV.INV_SEQ AND GR.STATUS != 'D') ,(SELECT GR.CLOSE_USER_ID FROM ICOMGRDT GR WHERE (GR.BUYER,GR.INV_NO,GR.INV_SEQ) = (SELECT WMS.BUYER,WMS.INV_NO,WMS.INV_SEQ FROM WMSIVDT WMS WHERE WMS.BUYER = IV.BUYER AND WMS.S_INV_NO = IV.INV_NO AND WMS.S_INV_SEQ = IV.INV_SEQ AND WMS.STATUS != 'D') AND GR.STATUS != 'D')) = #{st_ar_add_user_id}
